#!/bin/bash
# Load path configuration (DATA_ROOT, PROJECT_ROOT, TOOLS_ROOT, REF_ROOT, ...)
[ -f "${CONFIG_SH:-$(git rev-parse --show-toplevel 2>/dev/null)/config/config.sh}" ] && . "${CONFIG_SH:-$(git rev-parse --show-toplevel)/config/config.sh}"


#BSUB -P bindsc
#BSUB -J run_bindsc_reps45
#BSUB -q large_mem
#BSUB -R rusage[mem=150000]
#BSUB -n 1
#BSUB -o run_bindsc_reps45.log
#BSUB -e run_bindsc_reps45.err

# BindSC rep4 + rep5 (seeds 100, 200) -> res_Mast607A/rep4,rep5/coembed_coor.csv.
# rep1 = res_Mast607A/coembed_coor.csv; rep2/rep3 are generated by 02_reps23_sub.sh.
module load conda3/202210
conda activate bindsc

cd ${PROJECT_ROOT}/RMS/Mast607/script/bindsc

for rs in "rep4 100" "rep5 200"; do
  set -- $rs
  export REP=$1 SEED=$2
  echo "=== bindsc $REP (seed $SEED) ==="
  R CMD BATCH 01_run_bindsc.R run_bindsc_${REP}.Rout
done

conda deactivate
echo "DONE: res_Mast607A/rep4,rep5/coembed_coor.csv"
